Q: How to read the zip file contents in react application using jszip preferably A: <p>Don't know what the error is about, have you tried another zip file?</p>
<p>Anyway, here is my tsx code with reactjs hooks:</p>
<pre><code>  const [files, setFiles] = useState&lt;File[]&gt;(undefined);
  const [fileInfo, setFileInfo] = useState&lt;IFileInfo&gt;(undefined);

  useEffect(() =&gt; {
    if (files) {
      const f = files[0];
      const dateBefore = new Date();
      JSZip.loadAsync(f) // 1) read the Blob
      .then((zip) =&gt; {
          const contents = [];
          zip.forEach((relativePath, zipEntry) =&gt; {  // 2) print entries
            contents.push(zipEntry.name);
          });
          const loadTime = moment(new Date()).diff(moment(dateBefore));
          setFileInfo({
            loadTime,
            contents: contents.sort(),
            error: null
          });
      }, (e) =&gt; {
        const loadTime = moment(new Date()).diff(moment(dateBefore));
        setFileInfo({
          loadTime,
          contents: [],
          error: &quot;Error reading &quot; + f.name + &quot;: &quot; + e.message
        });
      });
    }
  }, [files]);

  // below some code that adds a file to files with drag and drop interface
</code></pre>

